// PL: Sprawdzamy frazę i limit wyszukiwań (ochrona kosztów AI) oraz zaglądamy do pamięci podręcznej.
// EN: We check the phrase and the search limit (AI cost guard) and look into the cache.
const first = $input.first().json || {};
const body = first.body || first || {};
const raw = String(body.query || '').replace(/\s+/g, ' ').trim();
const lang = body.lang === 'en' ? 'en' : 'pl';
const province = String(body.province || '').toLowerCase().trim();
const MSG = {
  short: { pl: 'Wpisz co najmniej 2 znaki.', en: 'Please enter at least 2 characters.' },
  long: { pl: 'Fraza jest za długa (maks. 160 znaków).', en: 'The phrase is too long (max 160 characters).' },
  busy: { pl: 'Dużo osób szuka w tej chwili. Spróbuj za kilka minut.', en: 'Many people are searching right now. Please try again in a few minutes.' }
};
const store = $getWorkflowStaticData('global');
const started_at = Date.now();
const key = (raw + '|' + province).toLowerCase();
const hit = store.cache && store.cache[key];
if (raw.length >= 2 && raw.length <= 160 && hit && Date.now() - hit.t < 15 * 60 * 1000) {
  return [{ json: { ok: true, cached: true, response: Object.assign({}, hit.data, { cached: true, lang, took_ms: 0 }), query: raw, lang, province, started_at } }];
}
const hour = new Date().toISOString().slice(0, 13);
if (store.hour !== hour) { store.hour = hour; store.count = 0; }
const LIMIT = 120; // PL: maks. wyszukiwań na godzinę / EN: max searches per hour
let ok = true;
let error = '';
if (raw.length < 2) { ok = false; error = MSG.short[lang]; }
else if (raw.length > 160) { ok = false; error = MSG.long[lang]; }
else if (store.count >= LIMIT) { ok = false; error = MSG.busy[lang]; }
else { store.count = (store.count || 0) + 1; }
return [{ json: { ok, cached: false, error, query: raw.slice(0, 160), lang, province, started_at } }];

// PL: Z odpowiedzi AI budujemy zapytania do BZP i TED. Gdy AI zawiedzie, używamy prostego planu B.
// EN: We build the BZP and TED requests from the AI answer. If AI fails, a simple plan B is used.
const input = $('Sprawdź zapytanie / Validate input').first().json;
const src = $input.first().json || {};
function textOf(j) {
  if (j && Array.isArray(j.output)) {
    for (const o of j.output) for (const c of (o.content || [])) if (c && c.text) return c.text;
  }
  if (j && typeof j.output === 'string') return j.output;
  if (j && j.text) return j.text;
  return '';
}
function extractJson(j) {
  const t = textOf(j);
  if (t && typeof t === 'object') return t;
  if (!t) return {};
  const m = String(t).match(/\{[\s\S]*\}/);
  if (!m) return {};
  try { return JSON.parse(m[0]); } catch (e) { return {}; }
}
const ai = extractJson(src);
const PROVINCES = { 'dolnośląskie': 'PL02', 'kujawsko-pomorskie': 'PL04', 'lubelskie': 'PL06', 'lubuskie': 'PL08', 'łódzkie': 'PL10', 'małopolskie': 'PL12', 'mazowieckie': 'PL14', 'opolskie': 'PL16', 'podkarpackie': 'PL18', 'podlaskie': 'PL20', 'pomorskie': 'PL22', 'śląskie': 'PL24', 'świętokrzyskie': 'PL26', 'warmińsko-mazurskie': 'PL28', 'wielkopolskie': 'PL30', 'zachodniopomorskie': 'PL32' };
const STOP = new Set(['dla', 'oraz', 'przy', 'the', 'and', 'for', 'with', 'from', 'tender', 'tenders', 'przetarg', 'przetargi', 'zamówienie', 'zamowienie']);
const words = input.query.toLowerCase().replace(/[^a-ząćęłńóśźż0-9\s-]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w));
const clean = (arr, min, max) => [...new Set((Array.isArray(arr) ? arr : []).map((s) => String(s).toLowerCase().replace(/[^a-ząćęłńóśźż0-9]/g, '')).filter((s) => s.length >= min && s.length <= max))];
let stems = clean(ai.stems, 3, 9).slice(0, 5);
const usedFallback = stems.length === 0;
if (usedFallback) stems = [...new Set(words.map((w) => w.replace(/[^a-ząćęłńóśźż0-9]/g, '').slice(0, Math.max(4, w.length - 2))))].filter((s) => s.length >= 3).slice(0, 4);
let keywords = clean(ai.keywords, 3, 20).slice(0, 4);
if (keywords.length === 0) keywords = [...new Set(words.map((w) => w.replace(/[^a-ząćęłńóśźż0-9]/g, '')))].slice(0, 3);
const cpv = [...new Set((Array.isArray(ai.cpv) ? ai.cpv : []).map((c) => String(c).replace(/\D/g, '').replace(/0+$/, '')).filter((c) => c.length >= 3).map((c) => c.slice(0, 5)))].slice(0, 3);
const typeMap = { works: 'Works', services: 'Services', delivery: 'Delivery' };
const orderType = typeMap[String(ai.order_type || '').toLowerCase()] || '';
const provName = String(input.province || ai.province || '').toLowerCase().trim();
const provCode = PROVINCES[provName] || '';
const now = new Date();
const iso = (d) => d.toISOString().slice(0, 19);
const from = iso(new Date(now.getTime() - 45 * 86400000));
const to = iso(new Date(now.getTime() + 86400000));
const open = iso(now);
const base = 'https://ezamowienia.gov.pl/mo-board/api/v1/Board/Search?noticeType=ContractNotice&publicationDateFrom=' + from + '&publicationDateTo=' + to + '&submittingOffersDateFrom=' + open + '&SortingColumnName=PublicationDate&SortingDirection=DESC&pageSize=10'
  + (provCode ? '&organizationProvince=' + provCode : '') + (orderType ? '&orderType=' + orderType : '');
const ctx = { query: input.query, lang: input.lang, started_at: input.started_at, stems, keywords, cpv, words: words.map((w) => w.slice(0, 5)), province: provName, order_type: String(ai.order_type || 'any').toLowerCase(), intent_pl: String(ai.intent_pl || ''), intent_en: String(ai.intent_en || ''), used_fallback: usedFallback };
const out = [];
for (const s of stems) for (const page of [1, 2, 3]) out.push({ json: { kind: 'stem', term: s, page, url: base + '&orderObject=' + encodeURIComponent(s) + '&pageNumber=' + page, ctx } });
for (const c of cpv) for (const page of [1, 2]) out.push({ json: { kind: 'cpv', term: c, page, url: base + '&cpvCode=' + c + '&pageNumber=' + page, ctx } });
const d = new Date(now.getTime() - 60 * 86400000);
const pad = (n) => String(n).padStart(2, '0');
const tedFrom = String(d.getUTCFullYear()) + pad(d.getUTCMonth() + 1) + pad(d.getUTCDate());
const tedParts = [];
for (const c of cpv) tedParts.push('classification-cpv=' + c + '*');
for (const k of keywords) tedParts.push('notice-title ~ ' + k);
const tedQuery = 'buyer-country=POL AND form-type=competition AND publication-date>=' + tedFrom + (tedParts.length ? ' AND (' + tedParts.join(' OR ') + ')' : '') + ' SORT BY publication-number DESC';
const tedBody = JSON.stringify({ query: tedQuery, fields: ['publication-number', 'notice-title', 'buyer-name', 'buyer-city', 'publication-date', 'deadline-receipt-tender-date-lot', 'classification-cpv', 'contract-nature', 'estimated-value-lot'], page: 1, limit: 30, scope: 'ACTIVE', paginationMode: 'PAGE_NUMBER' });
if (out.length) out[0].json.ted_body = tedBody;
return out.length ? out : [{ json: { kind: 'none', url: base + '&pageNumber=1&orderObject=zzzzzz', ctx, ted_body: tedBody } }];

// PL: Ujednolicamy ogłoszenia z BZP i TED, odrzucamy zakończone i usuwamy duplikaty (te same ogłoszenia z obu źródeł).
// EN: We unify BZP and TED notices, drop closed ones and remove duplicates (the same notice from both sources).
const ctx = $('Przygotuj zapytania / Build source queries').first().json.ctx;
const PROVINCES = { PL02: 'dolnośląskie', PL04: 'kujawsko-pomorskie', PL06: 'lubelskie', PL08: 'lubuskie', PL10: 'łódzkie', PL12: 'małopolskie', PL14: 'mazowieckie', PL16: 'opolskie', PL18: 'podkarpackie', PL20: 'podlaskie', PL22: 'pomorskie', PL24: 'śląskie', PL26: 'świętokrzyskie', PL28: 'warmińsko-mazurskie', PL30: 'wielkopolskie', PL32: 'zachodniopomorskie' };
const BZP_TYPES = { Delivery: 'delivery', Services: 'services', Works: 'works' };
const TED_TYPES = { supplies: 'delivery', services: 'services', works: 'works' };
const first = (v) => (Array.isArray(v) ? v[0] : v);
const pickText = (o) => { if (!o) return ''; if (typeof o === 'string') return o; const v = o.pol || o.eng || o.mul || Object.values(o)[0]; return String(first(v) || ''); };
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-ząćęłńóśźż0-9]/g, '');
const now = Date.now();
const rows = [];
for (const it of $input.all()) {
  const n = it.json || {};
  if (n.bzpNumber) {
    rows.push({ notice_id: n.bzpNumber, source: 'BZP', title: String(n.orderObject || '').replace(/\s+/g, ' ').trim(), cpv: [...new Set(String(n.cpvCode || '').match(/\d{8}/g) || [])].join(' '), buyer: String(n.organizationName || '').trim(), city: String(n.organizationCity || '').trim(), province: PROVINCES[n.organizationProvince] || '', order_type: BZP_TYPES[n.orderType] || '', published: n.publicationDate || null, deadline: n.submittingOffersDate || null, url: 'https://ezamowienia.gov.pl/mo-client-board/bzp/notice-details/id/' + n.objectId, object_id: n.objectId, below_eu: n.isTenderAmountBelowEU === true, est_value: null });
  } else if (Array.isArray(n.notices)) {
    for (const t of n.notices) {
      const pub = t['publication-number'];
      if (!pub) continue;
      let title = pickText(t['notice-title']).replace(/\s+/g, ' ').trim();
      const parts = title.split(' – ');
      if (parts.length >= 3) title = parts.slice(2).join(' – ');
      const dl = String(first(t['deadline-receipt-tender-date-lot']) || '').slice(0, 10);
      const pb = String(t['publication-date'] || '').slice(0, 10);
      const val = Number(first(t['estimated-value-lot']));
      rows.push({ notice_id: 'TED ' + pub, source: 'TED', title, cpv: [...new Set((t['classification-cpv'] || []).map((c) => String(c).slice(0, 8)))].join(' '), buyer: pickText(t['buyer-name']), city: pickText(t['buyer-city']), province: '', order_type: TED_TYPES[first(t['contract-nature'])] || '', published: pb ? pb + 'T00:00:00Z' : null, deadline: dl ? dl + 'T23:59:00+01:00' : null, url: 'https://ted.europa.eu/pl/notice/-/detail/' + pub, object_id: '', below_eu: false, est_value: Number.isFinite(val) && val > 0 ? val : null });
    }
  }
}
const byId = new Map();
for (const r of rows) {
  const dl = r.deadline ? Date.parse(r.deadline) : NaN;
  if (!isNaN(dl) && dl < now) continue;
  r.days_left = isNaN(dl) ? null : Math.max(0, Math.ceil((dl - now) / 86400000));
  const key = norm(r.title).slice(0, 60) + '|' + norm(r.buyer).slice(0, 25);
  const prev = byId.get(key);
  if (!prev || (r.source === 'TED' && prev.source === 'BZP')) byId.set(key, r);
}
const out = [...byId.values()].map((r) => ({ json: Object.assign({}, r, { q_stems: ctx.stems, q_cpv: ctx.cpv, q_words: ctx.words, q_province: ctx.province, q_type: ctx.order_type }) }));
return out.length ? out : [{ json: { _none: true } }];

// PL: Składamy gotową odpowiedź dla strony: 12 najlepszych wyników i krótkie podsumowanie. Zapamiętujemy ją na 15 minut.
// EN: We assemble the final answer for the page: the 12 best results and a short summary. We keep it for 15 minutes.
const ctx = $('Przygotuj zapytania / Build source queries').first().json.ctx;
const everything = $input.all().map((i) => i.json).filter((r) => r && !r._none);
// PL: Bardzo słabe trafienia (ocena poniżej 20) tylko zaszmiecają listę, więc je pomijamy, jeśli zostaje sensowna liczba.
// EN: Very weak matches (score below 20) only clutter the list, so we drop them when a sensible number remains.
const strong = everything.filter((r) => r.score >= 20);
const all = strong.length >= 3 ? strong : everything;
const level = (s) => (s >= 70 ? 'high' : s >= 45 ? 'medium' : 'low');
const results = all.slice(0, 12).map((r) => ({
  id: r.notice_id, source: r.source, title: r.title, buyer: r.buyer, city: r.city, province: r.province,
  order_type: r.order_type, cpv: String(r.cpv || '').split(' ').filter(Boolean).slice(0, 4), published: r.published, deadline: r.deadline,
  days_left: r.days_left, url: r.url, object_id: r.object_id, est_value: r.est_value, score: r.score, level: level(r.score), why_pl: r.why_pl, why_en: r.why_en
}));
const response = {
  ok: true,
  cached: false,
  query: ctx.query,
  lang: ctx.lang,
  understood: { pl: ctx.intent_pl, en: ctx.intent_en, stems: ctx.stems, cpv: ctx.cpv, fallback: ctx.used_fallback },
  total: all.length,
  counts: { BZP: all.filter((r) => r.source === 'BZP').length, TED: all.filter((r) => r.source === 'TED').length },
  took_ms: Date.now() - ctx.started_at,
  results
};
if (!ctx.used_fallback && all.length) {
  const store = $getWorkflowStaticData('global');
  store.cache = store.cache || {};
  store.cache[(ctx.query + '|' + (ctx.province || '')).toLowerCase()] = { t: Date.now(), data: response };
  const keys = Object.keys(store.cache);
  if (keys.length > 40) keys.sort((a, b) => store.cache[a].t - store.cache[b].t).slice(0, keys.length - 40).forEach((k) => { delete store.cache[k]; });
}
return [{ json: response }];

// PL: Sprawdzamy dane karty przetargu i pilnujemy limitu zapytań (ochrona kosztów AI).
// EN: We check the tender card request and guard the request limit (AI cost guard).
const first = $input.first().json || {};
const b = first.body || first || {};
const lang = b.lang === 'en' ? 'en' : 'pl';
const clean = (v, n) => String(v == null ? '' : v).split(' ').filter(Boolean).join(' ').slice(0, n);
const digits = (s) => String(s || '').split('').filter((ch) => ch >= '0' && ch <= '9').join('');
const cpvRaw = Array.isArray(b.cpv) ? b.cpv : String(b.cpv || '').split(' ');
const cpv = cpvRaw.map((c) => digits(c).slice(0, 8)).filter((c) => c.length >= 3).slice(0, 6);
const source = b.source === 'TED' ? 'TED' : 'BZP';
const objectId = clean(b.object_id, 60);
const idOk = objectId.length >= 20 && objectId.split('').every((ch) => '0123456789abcdefABCDEF-'.indexOf(ch) >= 0);
const store = $getWorkflowStaticData('global');
const hour = new Date().toISOString().slice(0, 13);
if (store.briefHour !== hour) { store.briefHour = hour; store.briefCount = 0; }
const LIMIT = 150; // PL: maks. kart na godzinę / EN: max cards per hour
const MSG = { bad: { pl: 'Brak danych przetargu.', en: 'Missing tender data.' }, busy: { pl: 'Dużo osób przegląda karty. Spróbuj za kilka minut.', en: 'Many people are opening cards right now. Please try again in a few minutes.' } };
let ok = true;
let error = '';
if (clean(b.title, 400).length < 3) { ok = false; error = MSG.bad[lang]; }
else if ((store.briefCount || 0) >= LIMIT) { ok = false; error = MSG.busy[lang]; }
else { store.briefCount = (store.briefCount || 0) + 1; }
let trimmed = cpv[0] || '';
while (trimmed.length > 3 && trimmed.charAt(trimmed.length - 1) === '0') trimmed = trimmed.slice(0, -1);
return [{ json: { ok, error, lang, id: clean(b.id, 80), source, object_id: idOk ? objectId : '', title: clean(b.title, 400), buyer: clean(b.buyer, 200), city: clean(b.city, 80), province: clean(b.province, 40), order_type: clean(b.order_type, 20), cpv, cpv5: trimmed.slice(0, 5), deadline: clean(b.deadline, 40), days_left: b.days_left == null ? null : Number(b.days_left), est_value: b.est_value == null ? null : Number(b.est_value), url: clean(b.url, 300), started_at: Date.now() } }];

// PL: Wyciągamy z treści ogłoszenia to, co ważne dla wykonawcy: opis, kryteria, wadium, czas realizacji.
// EN: We pull out what matters to a bidder: description, criteria, deposit, duration.
const card = $('Sprawdź kartę / Validate card request').first().json;
const raw = String(($input.first().json || {}).data || '');
const empty = { has_text: false, description: '', criteria: [], deposit: '', deposit_amount: '', duration: '', conditions: '' };
if (card.source !== 'BZP' || raw.length < 200 || raw.charAt(0) === '{') return [{ json: empty }];
const NL = String.fromCharCode(10);
const TAB = String.fromCharCode(9);
const txt = raw.replace(/<br[^>]*>/gi, NL).replace(/<[/](p|h[0-9]|div|li|tr)>/gi, NL).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').split(TAB).join(' ');
const lines = txt.split(NL).map((s) => s.split(' ').filter(Boolean).join(' ')).filter(Boolean);
const idx = (prefix, from) => { for (let i = from || 0; i < lines.length; i++) if (lines[i].indexOf(prefix) === 0) return i; return -1; };
const isLabel = (s) => /^[0-9]+[.][0-9]+/.test(s) || s.indexOf('SEKCJA') === 0;
let description = '';
const d0 = idx('4.2.2.) Krótki opis');
if (d0 >= 0) {
  const parts = [];
  for (let i = d0 + 1; i < lines.length && parts.join(' ').length < 900; i++) { if (isLabel(lines[i])) break; parts.push(lines[i]); }
  description = parts.join(' ').slice(0, 900);
}
const du = idx('4.2.10.) Okres realizacji');
const duration = du >= 0 ? lines[du].split(':').slice(1).join(':').trim().slice(0, 120) : '';
const c0 = idx('4.3.) Kryteria oceny');
const c1 = c0 >= 0 ? idx('4.3.2.)', c0) : -1;
const criteria = [];
if (c0 >= 0) for (let i = c0 + 1; i < (c1 > 0 ? c1 : c0 + 40) && i < lines.length; i++) { if (/^[0-9][)] .*(waga|%|pkt)/i.test(lines[i]) && criteria.length < 4) criteria.push(lines[i].replace(/[;.]$/, '').slice(0, 140)); }
const dp = idx('6.4.) Zamawiający wymaga wadium');
const deposit = dp >= 0 ? (lines[dp].indexOf('Tak') >= 0 ? 'yes' : 'no') : '';
const ma = txt.match(/wadium[^.]{0,120}?([0-9][0-9 ]{2,}(?:,[0-9]{1,2})?)[ ]*(?:zł|PLN)/i);
const cd = idx('5.3.) Warunki udziału');
const conditions = cd >= 0 ? (lines[cd].indexOf('Tak') >= 0 ? 'yes' : 'no') : '';
return [{ json: { has_text: true, description, criteria, deposit, deposit_amount: ma ? ma[1].split(' ').join(' ').trim() + ' PLN' : '', duration, conditions } }];

// PL: Szukamy podobnych, już rozstrzygniętych przetargów (ten sam kod branżowy, ostatnie 200 dni).
// EN: We look for similar tenders that are already decided (same industry code, last 200 days).
const card = $('Sprawdź kartę / Validate card request').first().json;
const now = new Date();
const iso = (d) => d.toISOString().slice(0, 19);
const from = iso(new Date(now.getTime() - 200 * 86400000));
const to = iso(now);
if (!card.cpv5) return [{ json: { url: 'https://ezamowienia.gov.pl/mo-board/api/v1/Config' } }];
const base = 'https://ezamowienia.gov.pl/mo-board/api/v1/Board/Search?noticeType=TenderResultNotice&publicationDateFrom=' + from + '&publicationDateTo=' + to + '&SortingColumnName=PublicationDate&SortingDirection=DESC&pageSize=10&cpvCode=' + card.cpv5;
return [1, 2, 3, 4].map((p) => ({ json: { url: base + '&pageNumber=' + p } }));

// PL: Zostawiamy tylko przetargi zakończone jedną umową z jednym wykonawcą (czyste dane do porównań).
// EN: We keep only tenders that ended with one contract and one contractor (clean data for comparison).
const rows = [];
for (const it of $input.all()) {
  const n = it.json || {};
  if (!n.bzpNumber) continue;
  const contractors = (n.contractors || []).filter((c) => c && c.contractorName);
  if (String(n.procedureResult || '') !== 'zawarcieUmowy' || contractors.length !== 1) continue;
  rows.push({ object_id: n.objectId, bzp: n.bzpNumber, published: n.publicationDate, winner: contractors[0].contractorName });
}
const pick = rows.slice(0, 30);
return pick.length ? pick.map((r) => ({ json: r })) : [{ json: { _none: true } }];

// PL: Z każdego ogłoszenia o wyniku odczytujemy liczbę ofert i ceny. Nazwy firm podajemy tylko dla spółek.
// EN: From each result notice we read the number of offers and the prices. Company names are shown only for companies.
const NL = String.fromCharCode(10);
const TAB = String.fromCharCode(9);
const meta = $('Wybierz pojedyncze umowy / Keep single contracts').all();
const num = (s) => { if (!s) return null; const v = Number(String(s).split(' ').join('').replace(',', '.')); return Number.isFinite(v) && v > 0 ? v : null; };
const NUM = '([0-9][0-9 ]*(?:,[0-9]+)?)';
const grab = (txt, label) => { const m = txt.match(new RegExp(label + '[ ]*' + NUM + '[ ]*PLN')); return m ? num(m[1]) : null; };
const FORMS = ['sp. z o.o', 'sp. z o. o', 'sp.z o.o', 'sp z o o', 'spółka', 'spolka', 's.a.', 'sp. k', 'sp.k', 'sp. j', 'sp.j', 'gmbh', 'ltd', 's.r.o', 'a.s.'];
const isCompany = (name) => { const n = String(name || '').toLowerCase(); return FORMS.some((f) => n.indexOf(f) >= 0) || n.slice(-3) === ' sa'; };
const out = [];
$input.all().forEach((it, i) => {
  const raw = String((it.json || {}).data || '');
  const m = meta[i] ? meta[i].json : {};
  if (!raw || raw.charAt(0) === '{' || m._none) return;
  const txt = raw.replace(/<br[^>]*>/gi, NL).replace(/<[/](p|h[0-9]|div|li|tr)>/gi, NL).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').split(TAB).join(' ');
  const flat = txt.split(NL).map((s) => s.split(' ').filter(Boolean).join(' ')).filter(Boolean).join(' | ');
  const win = grab(flat, 'wykonawcy, któremu udzielono zamówienia:');
  if (!win) return;
  const mo = flat.match(/Liczba otrzymanych ofert lub wniosków:[ ]*([0-9]+)/);
  out.push({ json: { notice: m.bzp || '', published: m.published || '', est: grab(flat, 'Wartość zamówienia[^:]*:'), win, min: grab(flat, 'najniższą ceną lub kosztem:'), max: grab(flat, 'najwyższą ceną lub kosztem:'), offers: mo ? Number(mo[1]) : null, winner: isCompany(m.winner) ? m.winner : 'Przedsiębiorca indywidualny / Sole trader' } });
});
return out.length ? out : [{ json: { _none: true } }];

// PL: Składamy w jedną paczkę to, co AI ma ocenić: przetarg, treść ogłoszenia i statystyki rynku.
// EN: We pack what the AI must assess: the tender, the notice text and the market statistics.
const card = $('Sprawdź kartę / Validate card request').first().json;
let facts = {};
try { facts = $('Wyciągnij dane z ogłoszenia / Extract notice facts').first().json; } catch (e) { facts = {}; }
let stats = {};
try { stats = $input.first().json || {}; } catch (e) { stats = {}; }
const payload = { tender: { title: card.title, buyer: card.buyer, city: card.city, province: card.province, type: card.order_type, cpv: card.cpv, deadline: card.deadline, days_left: card.days_left, estimated_value_pln: card.est_value }, notice_facts: facts, market_stats: stats };
return [{ json: { payload: JSON.stringify(payload) } }];

// PL: Składamy gotową kartę: fakty z ogłoszenia, statystyki rynku i ocenę AI.
// EN: We assemble the final card: notice facts, market statistics and the AI assessment.
const card = $('Sprawdź kartę / Validate card request').first().json;
let facts = {};
try { facts = $('Wyciągnij dane z ogłoszenia / Extract notice facts').first().json; } catch (e) { facts = {}; }
let stats = {};
try { stats = $('Policz statystyki (Python) / Compute statistics (Python)').first().json; } catch (e) { stats = {}; }
const src = $input.first().json || {};
function textOf(j) {
  if (j && Array.isArray(j.output)) { for (const o of j.output) for (const c of (o.content || [])) if (c && c.text) return c.text; }
  if (j && typeof j.output === 'string') return j.output;
  return '';
}
let ai = {};
const t = textOf(src);
if (t && typeof t === 'object') ai = t;
else if (t) { const s = String(t); const a = s.indexOf('{'); const z = s.lastIndexOf('}'); if (a >= 0 && z > a) { try { ai = JSON.parse(s.slice(a, z + 1)); } catch (e) { ai = {}; } } }
const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x)).slice(0, 4) : []);
const str = (v) => String(v || '').slice(0, 600);
const has = ai && (ai.summary_pl || ai.summary_en);
const brief = has ? { verdict: ['go', 'consider', 'skip'].indexOf(ai.verdict) >= 0 ? ai.verdict : 'consider', headline_pl: str(ai.headline_pl), headline_en: str(ai.headline_en), summary_pl: str(ai.summary_pl), summary_en: str(ai.summary_en), requirements_pl: arr(ai.requirements_pl), requirements_en: arr(ai.requirements_en), market_pl: str(ai.market_pl), market_en: str(ai.market_en), tips_pl: arr(ai.tips_pl), tips_en: arr(ai.tips_en), risks_pl: arr(ai.risks_pl), risks_en: arr(ai.risks_en) } : null;
return [{ json: { ok: true, id: card.id, source: card.source, url: card.url, facts, stats, brief, ai_ok: !!brief, took_ms: Date.now() - card.started_at } }];

// PL: Sprawdzamy frazę do obserwowania i pilnujemy limitu zapisów na godzinę.
// EN: We check the phrase to watch and guard the hourly limit of sign-ups.
const first = $input.first().json || {};
const b = first.body || first || {};
const lang = b.lang === 'en' ? 'en' : 'pl';
const phrase = String(b.query || '').split(' ').filter(Boolean).join(' ').slice(0, 120);
const store = $getWorkflowStaticData('global');
const hour = new Date().toISOString().slice(0, 13);
if (store.watchHour !== hour) { store.watchHour = hour; store.watchCount = 0; }
const MSG = { short: { pl: 'Wpisz co najmniej 3 znaki.', en: 'Please enter at least 3 characters.' }, busy: { pl: 'Za dużo zapisów w tej godzinie. Spróbuj później.', en: 'Too many sign-ups this hour. Please try later.' } };
let ok = true;
let error = '';
if (phrase.length < 3) { ok = false; error = MSG.short[lang]; }
else if ((store.watchCount || 0) >= 30) { ok = false; error = MSG.busy[lang]; }
else { store.watchCount = (store.watchCount || 0) + 1; }
return [{ json: { ok, error, lang, phrase, started_at: Date.now() } }];

// PL: Czy zapisać nową obserwację? Nie, jeśli taka już jest albo osiągnięto limit dla dema.
// EN: Should we save a new watch? Not if it already exists or the demo limit is reached.
const v = $('Sprawdź obserwację / Validate watch request').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.phrase);
const MAX = 20;
const dup = rows.find((r) => String(r.phrase).toLowerCase() === v.phrase.toLowerCase());
let action = 'create';
if (dup) action = 'exists';
else if (rows.length >= MAX) action = 'limit';
return [{ json: Object.assign({}, v, { action, total: rows.length, max: MAX }) }];

// PL: Zamieniamy odpowiedź AI na wpis do bazy: słowa kluczowe i kody branżowe do późniejszych alertów.
// EN: We turn the AI answer into a database entry: keywords and industry codes for later alerts.
const v = $('Zdecyduj / Decide').first().json;
const src = $input.first().json || {};
function textOf(j) {
  if (j && Array.isArray(j.output)) { for (const o of j.output) for (const c of (o.content || [])) if (c && c.text) return c.text; }
  if (j && typeof j.output === 'string') return j.output;
  return '';
}
let ai = {};
const t = textOf(src);
if (t && typeof t === 'object') ai = t;
else if (t) { const s = String(t); const a = s.indexOf('{'); const z = s.lastIndexOf('}'); if (a >= 0 && z > a) { try { ai = JSON.parse(s.slice(a, z + 1)); } catch (e) { ai = {}; } } }
const clean = (arr, min, max) => [...new Set((Array.isArray(arr) ? arr : []).map((s) => String(s).toLowerCase().replace(/[^a-ząćęłńóśźż0-9]/g, '')).filter((s) => s.length >= min && s.length <= max))];
let stems = clean(ai.stems, 3, 9).slice(0, 4);
if (!stems.length) stems = [...new Set(v.phrase.toLowerCase().replace(/[^a-ząćęłńóśźż0-9 ]/g, ' ').split(' ').filter((w) => w.length > 2).map((w) => w.slice(0, Math.max(4, w.length - 2))))].slice(0, 4);
const cpv = [...new Set((Array.isArray(ai.cpv) ? ai.cpv : []).map((c) => String(c).split('').filter((ch) => ch >= '0' && ch <= '9').join('')).filter((c) => c.length >= 3).map((c) => c.slice(0, 5)))].slice(0, 2);
const now = new Date().toISOString();
return [{ json: { phrase: v.phrase, keywords: stems.join(','), cpv_prefixes: cpv.join(','), lang: v.lang, created: now, last_checked: now, hits_total: 0, active: true } }];

// PL: Dla każdej obserwowanej frazy pytamy BZP o otwarte ogłoszenia z ostatniej doby.
// EN: For each watched phrase we ask BZP for open notices from the last 24 hours.
const now = new Date();
const iso = (d) => d.toISOString().slice(0, 19);
const from = iso(new Date(now.getTime() - 24 * 3600 * 1000));
const to = iso(new Date(now.getTime() + 86400000));
const open = iso(now);
const out = [];
for (const it of $input.all()) {
  const w = it.json;
  if (!w || !w.phrase) continue;
  const base = 'https://ezamowienia.gov.pl/mo-board/api/v1/Board/Search?noticeType=ContractNotice&publicationDateFrom=' + from + '&publicationDateTo=' + to + '&submittingOffersDateFrom=' + open + '&SortingColumnName=PublicationDate&SortingDirection=DESC&pageSize=10&pageNumber=1';
  const stems = String(w.keywords || '').split(',').filter(Boolean).slice(0, 4);
  const cpvs = String(w.cpv_prefixes || '').split(',').filter(Boolean).slice(0, 2);
  stems.forEach((s) => out.push({ json: { phrase: w.phrase, lang: w.lang, url: base + '&orderObject=' + encodeURIComponent(s) } }));
  cpvs.forEach((c) => out.push({ json: { phrase: w.phrase, lang: w.lang, url: base + '&cpvCode=' + c } }));
}
return out;

// PL: Wybieramy tylko te ogłoszenia, których dana fraza jeszcze nie dostała, i składamy wiadomość na Telegram.
// EN: We keep only the notices this phrase has not received yet and compose the Telegram message.
const NL = String.fromCharCode(10);
const reqs = $('Zapytania dla fraz / Build alert requests').all();
const fetched = $('Pobierz nowe z BZP / Fetch new from BZP').all();
const logRows = $('Wczytaj dziennik alertów / Load alert log').all().map((i) => i.json);
const sent = new Set(logRows.filter((r) => r && r.notice_id).map((r) => String(r.phrase || '') + '|' + String(r.notice_id)));
const now = Date.now();
const groups = new Map();
// PL: Każde zapytanie daje dokładnie jedną odpowiedź, w tej samej kolejności, więc wiemy, do jakiej frazy należy.
// EN: Each request gives exactly one response in the same order, so we know which phrase it belongs to.
fetched.forEach((it, i) => {
  const src = reqs[i] ? reqs[i].json : null;
  if (!src || !src.phrase) return;
  const body = it.json && Array.isArray(it.json.body) ? it.json.body : [];
  for (const n of body) {
    if (!n || !n.bzpNumber) continue;
    const dl = n.submittingOffersDate ? Date.parse(n.submittingOffersDate) : NaN;
    if (!isNaN(dl) && dl < now) continue;
    if (sent.has(src.phrase + '|' + n.bzpNumber)) continue;
    if (!groups.has(src.phrase)) groups.set(src.phrase, new Map());
    groups.get(src.phrase).set(n.bzpNumber, { notice_id: n.bzpNumber, title: String(n.orderObject || '').split(' ').filter(Boolean).join(' '), buyer: String(n.organizationName || ''), city: String(n.organizationCity || ''), days_left: isNaN(dl) ? null : Math.max(0, Math.ceil((dl - now) / 86400000)), url: 'https://ezamowienia.gov.pl/mo-client-board/bzp/notice-details/id/' + n.objectId });
  }
});
const esc = (s) => String(s || '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const out = [];
for (const [phrase, map] of groups) {
  const list = [...map.values()];
  if (!list.length) continue;
  const lines = list.slice(0, 5).map((r) => '• <a href="' + r.url + '">' + esc(r.title.slice(0, 110)) + '</a>' + NL + '   ' + esc(r.buyer.slice(0, 60)) + (r.city ? ', ' + esc(r.city) : '') + (r.days_left != null ? ' · ' + r.days_left + ' dni / days' : ''));
  const more = list.length > 5 ? NL + '… +' + (list.length - 5) : '';
  const text = '🔔 <b>Radar Przetargów · Tender Radar</b>' + NL + '<b>' + esc(phrase) + '</b>: ' + list.length + ' nowych / new' + NL + NL + lines.join(NL + NL) + more;
  out.push({ json: { phrase, text, notices: list } });
}
return out;

// PL: Zapisujemy, co zostało wysłane, żeby nie wysyłać tego ponownie.
// EN: We record what was sent so we do not send it again.
const rows = [];
const nowIso = new Date().toISOString();
for (const it of $('Wybierz nowe ogłoszenia / Pick new notices').all()) {
  for (const r of (it.json.notices || [])) rows.push({ json: { notice_id: r.notice_id, phrase: it.json.phrase, title: String(r.title).slice(0, 200), url: r.url, sent_at: nowIso } });
}
return rows;

// PL: Sprawdzamy, czy oba źródła zwróciły dane, i przygotowujemy ostrzeżenie, jeśli nie.
// EN: We check that both sources returned data and prepare a warning if not.
const NL = String.fromCharCode(10);
const b = $('Sprawdź BZP / Check BZP').first().json || {};
const t = $('Sprawdź TED / Check TED').first().json || {};
const bzpOk = !!b.bzpNumber;
const tedOk = Array.isArray(t.notices) && t.notices.length > 0;
const ts = new Date().toISOString();
const problems = [];
if (!bzpOk) problems.push('BZP');
if (!tedOk) problems.push('TED');
const text = problems.length ? '⚠️ <b>Radar Przetargów · Tender Radar</b>' + NL + 'Źródło nie odpowiada / Source not responding: <b>' + problems.join(', ') + '</b>' + NL + ts.slice(0, 16).split('T').join(' ') + ' UTC' : '';
return [{ json: { ts, bzp_ok: bzpOk, ted_ok: tedOk, problems, has_problem: problems.length > 0, text, state_value: JSON.stringify({ ts, bzp_ok: bzpOk, ted_ok: tedOk }) } }];

// PL: Zamieniamy zapisany wynik kontroli na prostą odpowiedź dla strony.
// EN: We turn the stored check result into a simple answer for the page.
const row = $input.first().json || {};
let st = {};
try { st = JSON.parse(row.state_value || '{}'); } catch (e) { st = {}; }
const known = !!st.ts;
const label = (ok) => (!known ? 'unknown' : ok === true ? 'ok' : 'down');
return [{ json: { ok: true, known, checked_at: st.ts || null, sources: { BZP: label(st.bzp_ok), TED: label(st.ted_ok) } } }];

assignments.value:
:root{--bg:#fff;--ink:#0f172a;--mut:#5b6b82;--line:#e4e9f0;--soft:#f5f7fa;--ac:#1d4ed8;--acs:#eef3ff;--good:#157347;--goods:#e8f5ee;--warn:#b45309;--warns:#fdf3e4;--r:14px}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,-apple-system,'Segoe UI',Roboto,sans-serif}
a{color:var(--ac)}
.wrap{max-width:940px;margin:0 auto;padding:0 20px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.top{border-bottom:1px solid var(--line);background:rgba(255,255,255,.92);backdrop-filter:blur(8px);position:sticky;top:0;z-index:5}
.bar{display:flex;align-items:center;justify-content:space-between;gap:12px;height:60px}
.brand{display:flex;align-items:center;gap:10px;font-weight:650;letter-spacing:-.01em}
.logo{width:22px;height:22px;border-radius:50%;border:2px solid var(--ac);position:relative;flex:none}
.logo:after{content:'';position:absolute;inset:4px;border-radius:50%;background:var(--ac)}
.bar-right{display:flex;align-items:center;gap:16px}
.status{font-size:13px;color:var(--mut);display:flex;align-items:center;gap:6px}
.status i{width:8px;height:8px;border-radius:50%;background:var(--good);display:inline-block}
.status.bad i{background:var(--warn)}
.lang{display:flex;border:1px solid var(--line);border-radius:999px;padding:2px}
.lang button{border:0;background:none;padding:4px 12px;border-radius:999px;font:inherit;font-size:13px;font-weight:600;color:var(--mut);cursor:pointer}
.lang button[aria-pressed=true]{background:var(--ink);color:#fff}
.hero{padding:56px 20px 24px;text-align:center}
h1{font-size:clamp(28px,5.2vw,44px);line-height:1.12;letter-spacing:-.03em;margin:0 0 14px}
.lead{max-width:640px;margin:0 auto 28px;color:var(--mut);font-size:17px}
.search{display:flex;gap:8px;max-width:780px;margin:0 auto;padding:8px;border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 30px rgba(15,23,42,.06);background:#fff;align-items:center}
.search:focus-within{border-color:var(--ac);box-shadow:0 0 0 4px var(--acs)}
.search input{flex:1;min-width:0;border:0;outline:0;font:inherit;font-size:17px;padding:10px 12px;background:none;color:var(--ink)}
.search select{border:0;border-left:1px solid var(--line);background:none;font:inherit;font-size:14px;color:var(--mut);padding:6px 8px;max-width:150px;outline:0;cursor:pointer}
.btn{border:0;border-radius:12px;background:var(--ac);color:#fff;font:inherit;font-weight:600;padding:10px 22px;cursor:pointer;text-decoration:none;display:inline-block}
.btn:hover{filter:brightness(1.08)}
.btn:disabled{opacity:.6;cursor:default}
.btn.soft{background:var(--acs);color:var(--ac);padding:8px 16px;font-size:14px}
.btn.ghost{background:#fff;color:var(--ink);border:1px solid var(--line);padding:8px 16px;font-size:14px}
:focus-visible{outline:3px solid var(--ac);outline-offset:2px}
.chips{margin-top:16px;color:var(--mut);font-size:14px}
.chip{margin:4px 3px;border:1px solid var(--line);background:#fff;color:var(--ink);padding:5px 12px;border-radius:999px;font:inherit;font-size:14px;cursor:pointer}
.chip:hover{border-color:var(--ac);color:var(--ac)}
#results{min-height:60px;padding-bottom:30px}
.rhead{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin:18px 0 6px;padding:14px 16px;background:var(--soft);border-radius:var(--r)}
.rhead p{margin:0;font-size:15px}
.rhead .und{color:var(--mut);font-size:14px;margin-top:2px}
.card{display:flex;gap:16px;border:1px solid var(--line);border-radius:var(--r);padding:18px;margin:12px 0;background:#fff;transition:box-shadow .15s}
.card:hover{box-shadow:0 6px 24px rgba(15,23,42,.06)}
.score{--c:var(--mut);flex:none;width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--c) calc(var(--p)*1%),var(--line) 0);position:relative}
.score:before{content:'';position:absolute;inset:5px;background:#fff;border-radius:50%}
.score b{position:relative;font-size:16px}
.score.l-high{--c:var(--good)}
.score.l-medium{--c:var(--ac)}
.score.l-low{--c:#94a3b8}
.cbody{min-width:0;flex:1}
.meta{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:12px}
.tag{border:1px solid var(--line);border-radius:6px;padding:1px 8px;color:var(--mut);font-weight:600}
.lvl{color:var(--mut)}
h3{margin:6px 0 4px;font-size:18px;line-height:1.3;letter-spacing:-.01em;overflow-wrap:anywhere}
.buyer{margin:0;color:var(--mut);font-size:14px}
.when{margin:6px 0 0;font-size:14px}
.when.warn{color:var(--warn);font-weight:600}
.why{list-style:none;padding:0;margin:10px 0 0;display:flex;flex-wrap:wrap;gap:6px}
.why li{background:var(--soft);border-radius:999px;padding:2px 10px;font-size:12px;color:var(--mut)}
.actions{display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin-top:14px}
.link{font-size:14px;text-decoration:none;font-weight:600}
.link:hover{text-decoration:underline}
.brief{margin-top:16px;border-top:1px dashed var(--line);padding-top:16px}
.verdict{display:flex;flex-wrap:wrap;gap:6px 12px;align-items:baseline;padding:10px 14px;border-radius:10px;background:var(--soft)}
.verdict strong{font-size:15px}
.verdict span{color:var(--mut);font-size:14px}
.v-go{background:var(--goods)}
.v-go strong{color:var(--good)}
.v-consider{background:var(--warns)}
.v-consider strong{color:var(--warn)}
.sum{margin:12px 0}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 24px}
.sec h4{margin:0 0 6px;font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--mut)}
.sec ul{margin:0;padding-left:18px;font-size:14px}
.sec li{margin:3px 0}
.full{grid-column:1/-1}
.kv{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;font-size:14px;margin:0}
.kv dt{color:var(--mut)}
.kv dd{margin:0}
.gauge{position:relative;height:10px;background:var(--soft);border-radius:99px;margin:32px 8px 28px}
.band{position:absolute;top:0;bottom:0;background:#c7d5fb;border-radius:99px}
.est{position:absolute;top:-7px;bottom:-7px;width:2px;background:var(--ink)}
.est small,.dot small{position:absolute;white-space:nowrap;font-size:11px;color:var(--mut);left:50%;transform:translateX(-50%)}
.est small{top:100%;margin-top:3px}
.dot{position:absolute;top:50%;width:16px;height:16px;margin:-8px 0 0 -8px;background:var(--ac);border:3px solid #fff;border-radius:50%;box-shadow:0 0 0 1px var(--ac)}
.dot small{bottom:100%;margin-bottom:4px;color:var(--ac);font-weight:700;font-size:12px}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:8px}
.stat{background:var(--soft);border-radius:10px;padding:10px 12px}
.stat b{display:block;font-size:18px}
.stat span{font-size:12px;color:var(--mut)}
.muted{color:var(--mut);font-size:14px}
.note{background:var(--warns);border-radius:10px;padding:10px 14px;font-size:14px;margin:0 0 12px}
.disc{font-size:12px;color:var(--mut);margin:14px 0 0}
.skel{display:grid;gap:10px}
.skel i{display:block;height:14px;border-radius:7px;background:linear-gradient(90deg,var(--soft),#e9eef5,var(--soft));background-size:200% 100%;animation:sh 1.3s infinite}
.skel i:nth-child(2){width:80%}
.skel i:nth-child(3){width:60%}
@keyframes sh{to{background-position:-200% 0}}
.loader{text-align:center;padding:48px 0;color:var(--mut)}
.spin{width:30px;height:30px;border:3px solid var(--line);border-top-color:var(--ac);border-radius:50%;margin:0 auto 14px;animation:rot .8s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.empty{text-align:center;color:var(--mut);padding:40px 10px}
.how{padding-top:34px;padding-bottom:20px}
.how h2{font-size:22px;letter-spacing:-.02em;margin:0 0 16px}
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.steps div{border:1px solid var(--line);border-radius:var(--r);padding:16px}
.steps b{display:block;margin-bottom:4px}
.steps p{margin:0;color:var(--mut);font-size:14px}
footer{border-top:1px solid var(--line);margin-top:30px;padding:22px 0;color:var(--mut);font-size:13px}
footer p{margin:4px 0}
.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--ink);color:#fff;padding:12px 18px;border-radius:12px;max-width:min(560px,90vw);font-size:14px;z-index:20;box-shadow:0 10px 30px rgba(0,0,0,.25)}
[hidden]{display:none!important}
@media(max-width:700px){.grid,.steps{grid-template-columns:1fr}.card{flex-direction:column;gap:10px}.search{flex-wrap:wrap}.search input{flex:1 1 100%}.search select{border-left:0;flex:1}.bar-right{gap:8px}.status span{display:none}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}

(function () {
