    if (sv === 'pl' || sv === 'en') lang = sv;
    else if (String(navigator.language || '').slice(0, 2) === 'en') lang = 'en';
  } catch (e) {}
  var state = { query: '', data: null, cache: {}, status: null };
  var timer = null;
  var toastTimer = null;

  function $(id) { return document.getElementById(id); }
  function esc(s) { return String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split(String.fromCharCode(39)).join('&#39;'); }
  function t(k, v) {
    var s = T[lang][k] != null ? T[lang][k] : k;
    if (v) Object.keys(v).forEach(function (n) { s = s.split('{' + n + '}').join(v[n]); });
    return s;
  }
  function safeUrl(u) { u = String(u || ''); return u.indexOf('https://') === 0 ? u : '#'; }
  function loc() { return lang === 'pl' ? 'pl-PL' : 'en-GB'; }
  function fmtDate(iso) { var d = new Date(iso); return isNaN(d) ? '' : d.toLocaleDateString(loc(), { day: 'numeric', month: 'short', year: 'numeric' }); }
  function pln(n) { return new Intl.NumberFormat(loc(), { maximumFractionDigits: 0 }).format(n) + ' PLN'; }
  function pct(x) { return Math.round(Number(x) * 100) + '%'; }
  function cap(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }
  function pickText(o, k) { return (lang === 'pl' ? o[k + '_pl'] : o[k + '_en']) || ''; }
  function pickList(o, k) { return (lang === 'pl' ? o[k + '_pl'] : o[k + '_en']) || []; }
  function items(a) { return (a || []).map(function (x) { return '<li>' + esc(x) + '</li>'; }).join(''); }

  function toast(msg) {
    var n = $('toast');
    n.textContent = msg;
    n.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { n.hidden = true; }, 7000);
  }

  function post(path, body, ms) {
    var ctl = typeof AbortController === 'function' ? new AbortController() : null;
    var to = setTimeout(function () { if (ctl) ctl.abort(); }, ms || 45000);
    return fetch(API + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), signal: ctl ? ctl.signal : undefined })
      .then(function (r) { clearTimeout(to); return r.json(); });
  }

  function applyLang() {
    document.documentElement.lang = lang;
    document.title = t('title');
    Array.prototype.forEach.call(document.querySelectorAll('[data-i18n]'), function (n) { n.textContent = t(n.getAttribute('data-i18n')); });
    Array.prototype.forEach.call(document.querySelectorAll('[data-i18n-ph]'), function (n) { n.setAttribute('placeholder', t(n.getAttribute('data-i18n-ph'))); });
    $('l-pl').setAttribute('aria-pressed', String(lang === 'pl'));
    $('l-en').setAttribute('aria-pressed', String(lang === 'en'));
    var sel = $('prov');
    var cur = sel.value;
    sel.innerHTML = '';
    var o0 = document.createElement('option');
    o0.value = '';
    o0.textContent = t('all');
    sel.appendChild(o0);
    PROV.forEach(function (p) { var o = document.createElement('option'); o.value = p; o.textContent = cap(p); sel.appendChild(o); });
    sel.value = cur;
    var ch = $('chips');
    ch.innerHTML = '';
    EX[lang].forEach(function (q) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'chip';
      b.textContent = q;
      b.addEventListener('click', function () { $('q').value = q; doSearch(q); });
      ch.appendChild(b);
    });
    renderStatus();
    if (state.data) renderResults();
  }

  function setLang(l) {
    lang = l;
    try { localStorage.setItem('radar_lang', l); } catch (e) {}
    applyLang();
  }

  function startLoader() {
    var i = 0;
    $('results').innerHTML = `<div class='loader'><div class='spin'></div><p id='lmsg'>${esc(t('s0'))}</p></div>`;
    clearInterval(timer);
    timer = setInterval(function () { i = Math.min(i + 1, 3); var m = $('lmsg'); if (m) m.textContent = t('s' + i); }, 1800);
  }

  function stopLoader() { clearInterval(timer); timer = null; }

  function showError(msg) {
    $('results').innerHTML = `<div class='empty'><p>${esc(msg || t('err'))}</p><button type='button' class='btn soft' data-act='retry'>${esc(t('retry'))}</button></div>`;
  }

  function doSearch(q) {
    q = String(q || '').trim();
    if (q.length < 2) { toast(t('short')); return; }
    state.query = q;
    state.cache = {};
    state.data = null;
    startLoader();
    post('radar-search', { query: q, lang: lang, province: $('prov').value }, 60000).then(function (d) {
      stopLoader();
      if (!d || d.ok !== true) { showError(d && d.error); return; }
      state.data = d;
      renderResults();
    }).catch(function () { stopLoader(); showError(); });
  }

  function card(r, i) {
    var typ = r.order_type ? t('ty_' + r.order_type) : '';
    var rel = r.days_left == null ? '' : (r.days_left === 0 ? t('today') : (r.days_left === 1 ? t('tomorrow') : t('inDays', { n: r.days_left })));
    var warn = r.days_left != null && r.days_left <= 3;
    var why = (lang === 'pl' ? r.why_pl : r.why_en) || [];
    var place = [r.city, r.province].filter(Boolean).join(', ');
    var sc = Number(r.score) || 0;
    return `<article class='card' data-i='${i}'>
      <div class='score l-${esc(r.level)}' style='--p:${sc}' title='${esc(t('lv_' + r.level))}'><b>${sc}</b></div>
      <div class='cbody'>
        <div class='meta'><span class='tag'>${esc(r.source)}</span>${typ ? `<span class='tag'>${esc(typ)}</span>` : ''}<span class='lvl'>${esc(t('lv_' + r.level))}</span></div>
        <h3>${esc(r.title)}</h3>
        <p class='buyer'>${esc(r.buyer)}${place ? ' · ' + esc(place) : ''}</p>
        <p class='when${warn ? ' warn' : ''}'>${esc(t('deadline'))}: ${esc(fmtDate(r.deadline))}${rel ? ' · ' + esc(rel) : ''}${r.est_value ? ' · ' + esc(t('value')) + ': ' + esc(pln(r.est_value)) : ''}</p>
        ${why.length ? `<ul class='why'>${items(why)}</ul>` : ''}
        <div class='actions'><button type='button' class='btn soft' data-act='brief' aria-expanded='false'>${esc(t('analyze'))}</button><a class='link' href='${esc(safeUrl(r.url))}' target='_blank' rel='noopener noreferrer'>${esc(t('original'))} ↗</a></div>
        <div class='brief' hidden></div>
      </div>
    </article>`;
  }

  function renderResults() {
    var d = state.data;
    var box = $('results');
    if (!d) return;
    if (!d.results || !d.results.length) { box.innerHTML = `<div class='empty'>${esc(t('none'))}</div>`; return; }
    var und = d.understood ? (lang === 'pl' ? d.understood.pl : d.understood.en) : '';
    var head = `<div class='rhead'><div><p><b>${esc(t('found', { n: d.total, b: d.counts.BZP, d: d.counts.TED, m: d.results.length }))}</b>${d.cached ? ' · ' + esc(t('cachedn')) : ''}</p>${und ? `<p class='und'>${esc(t('under'))} ${esc(und)}</p>` : ''}</div><button type='button' class='btn ghost' id='watchbtn'>${esc(t('watch'))}</button></div><p class='muted'>${esc(t('watchnote'))}</p>`;
    box.innerHTML = head + d.results.map(card).join('');
    $('watchbtn').addEventListener('click', watch);
  }

  function marketHtml(s) {
    if (!s || !s.n) return `<p class='muted'>${esc(t('nomarket'))}</p>`;
    var out = '';
    if (s.median_ratio) {
      var lo = 0.7, hi = 1.5;
      var at = function (v) { return Math.max(0, Math.min(100, ((v - lo) / (hi - lo)) * 100)); };
      var a = at(s.p25_ratio || s.median_ratio);
      var z = at(s.p75_ratio || s.median_ratio);
      out += `<p class='muted' style='margin:0'>${esc(t('m_ratio'))}</p><div class='gauge'><span class='band' style='left:${a}%;width:${Math.max(2, z - a)}%'></span><span class='est' style='left:${at(1)}%'><small>${esc(t('m_est'))}</small></span><span class='dot' style='left:${at(s.median_ratio)}%'><small>${pct(s.median_ratio)}</small></span></div>`;
    }
    var st = [];
    if (s.avg_offers != null) st.push([Number(s.avg_offers).toFixed(1), t('m_offers')]);
    if (s.single_offer_share != null) st.push([pct(s.single_offer_share), t('m_single')]);
    if (s.below_estimate_share != null) st.push([pct(s.below_estimate_share), t('m_below')]);
    if (s.median_win_pln) st.push([pln(s.median_win_pln), t('m_win')]);
    out += `<div class='stats'>${st.map(function (x) { return `<div class='stat'><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div>`; }).join('')}</div>`;
    if (s.top_winners && s.top_winners.length) out += `<p class='muted' style='margin:10px 0 0'><b>${esc(t('m_top'))}:</b> ${s.top_winners.map(function (w) { return esc(w.name) + ' (' + w.wins + ')'; }).join('; ')}</p>`;
    out += `<p class='muted' style='margin:8px 0 0'>${esc(t('m_n', { n: s.n }))}</p>`;
    return out;
  }

  function briefHtml(b) {
    var br = b.brief;
    var f = b.facts || {};
    var out = '';
    if (br) out += `<div class='verdict v-${esc(br.verdict)}'><strong>${esc(t('v_' + br.verdict))}</strong><span>${esc(pickText(br, 'headline'))}</span></div><p class='sum'>${esc(pickText(br, 'summary'))}</p>`;
    else out += `<p class='note'>${esc(t('noai'))}</p>`;
    var facts = [];
    if (f.deposit === 'yes') facts.push([t('f_deposit'), f.deposit_amount ? t('yes') + ' · ' + f.deposit_amount : t('yes')]);
    if (f.deposit === 'no') facts.push([t('f_deposit'), t('no')]);
    if (f.duration) facts.push([t('f_duration'), f.duration]);
    if (f.conditions) facts.push([t('f_cond'), f.conditions === 'yes' ? t('yes') : t('no')]);
    (f.criteria || []).forEach(function (c) { facts.push([t('f_crit'), c]); });
    var req = br ? pickList(br, 'requirements') : [];
    var tips = br ? pickList(br, 'tips') : [];
    var risks = br ? pickList(br, 'risks') : [];
    out += `<div class='grid'>`;
    if (req.length) out += `<div class='sec'><h4>${esc(t('sec_req'))}</h4><ul>${items(req)}</ul></div>`;
    if (facts.length) out += `<div class='sec'><h4>${esc(t('sec_facts'))}</h4><dl class='kv'>${facts.map(function (x) { return '<dt>' + esc(x[0]) + '</dt><dd>' + esc(x[1]) + '</dd>'; }).join('')}</dl></div>`;
    out += `<div class='sec full'><h4>${esc(t('sec_market'))}</h4>${br && pickText(br, 'market') ? `<p style='margin:0 0 4px'>${esc(pickText(br, 'market'))}</p>` : ''}${marketHtml(b.stats)}</div>`;
    if (tips.length) out += `<div class='sec'><h4>${esc(t('sec_tips'))}</h4><ul>${items(tips)}</ul></div>`;
    if (risks.length) out += `<div class='sec'><h4>${esc(t('sec_risks'))}</h4><ul>${items(risks)}</ul></div>`;
    out += `</div><p class='disc'>${esc(t('disc'))}</p>`;
    return out;
  }

  function toggleBrief(cardEl, i, btn) {
    var box = cardEl.querySelector('.brief');
    var r = state.data.results[i];
    if (!box.hidden) { box.hidden = true; btn.setAttribute('aria-expanded', 'false'); btn.textContent = t('analyze'); return; }
    box.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    btn.textContent = t('hide');
    if (state.cache[r.id]) { box.innerHTML = briefHtml(state.cache[r.id]); return; }
    box.innerHTML = `<div class='skel'><i></i><i></i><i></i></div>`;
    post('radar-brief', { id: r.id, source: r.source, object_id: r.object_id, title: r.title, buyer: r.buyer, city: r.city, province: r.province, order_type: r.order_type, cpv: r.cpv, deadline: r.deadline, days_left: r.days_left, est_value: r.est_value, url: r.url, lang: lang }, 70000).then(function (b) {
      if (!b || b.ok !== true) { box.innerHTML = `<p class='note'>${esc((b && b.error) || t('err'))}</p>`; return; }
      state.cache[r.id] = b;
      box.innerHTML = briefHtml(b);
    }).catch(function () { box.innerHTML = `<p class='note'>${esc(t('err'))}</p>`; });
  }

  function watch() {
    if (!state.query) return;
    var btn = $('watchbtn');
    btn.disabled = true;
    post('radar-watch', { query: state.query, lang: lang }, 40000).then(function (d) {
      btn.disabled = false;
      toast(d && d.ok === false ? d.error : (lang === 'pl' ? d.message_pl : d.message_en));
    }).catch(function () { btn.disabled = false; toast(t('err')); });
  }

  function renderStatus() {
    var s = state.status;
    var box = $('status');
    if (!s || !s.known) { box.hidden = true; return; }
    var bad = s.sources.BZP !== 'ok' || s.sources.TED !== 'ok';
    box.hidden = false;
    box.className = 'status' + (bad ? ' bad' : '');
    $('stxt').textContent = bad ? t('st_bad') : t('st_ok');
  }

  function loadStatus() {
    fetch(API + 'radar-status').then(function (r) { return r.json(); }).then(function (s) { state.status = s; renderStatus(); }).catch(function () {});
  }

  $('results').addEventListener('click', function (e) {
    var b = e.target.closest ? e.target.closest('[data-act]') : null;
    if (!b) return;
    var act = b.getAttribute('data-act');
    var c = b.closest('.card');
    if (act === 'brief' && c) toggleBrief(c, Number(c.getAttribute('data-i')), b);
    if (act === 'retry') doSearch(state.query);
  });
  $('f').addEventListener('submit', function (e) { e.preventDefault(); doSearch($('q').value); });
  $('l-pl').addEventListener('click', function () { setLang('pl'); });
  $('l-en').addEventListener('click', function () { setLang('en'); });
  applyLang();
  loadStatus();
  try {
    var qp = new URLSearchParams(location.search).get('q');
    if (qp) { $('q').value = qp; doSearch(qp); }
  } catch (e) {}
})();

