// PL: Składamy trzy części w jeden dokument HTML.
// EN: We join the three parts into one HTML document.
const f = $input.first().json;
const html = '<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Radar Przetargów · Tender Radar</title><meta name="description" content="Wyszukiwarka przetargów publicznych PL/EN. Public tenders search PL/EN."><style>' + f.page_css + '</style></head><body>' + f.page_body + '<script>' + f.page_js + '</script></body></html>';
return [{ json: { html } }];
